// ================= TES PARAMÈTRES : ÉCRIS ICI =================
// 1. Dépose ton livre dans le dossier  atelier-ecriture/livres/
//    Formats acceptés : .pdf (avec texte, pas un scan), .txt, .md
//    (.epub : le convertir d'abord en .txt, ex. avec Calibre)
// 2. Écris son nom exact ci-dessous, puis « Execute Workflow ».
// 3. Le résumé arrive dans  atelier-ecriture/sorties/resume-....md
// ⚠️ Ne touche qu'au texte entre les guillemets.
// ==============================================================
return [{ json: {
  fichier: "candide.txt",
  niveau: "detaille",      // "court" (1 page) ou "detaille" (fiche complète + annexes)
  consigne: "",            // optionnel : un angle, ex. "insiste sur les idées de management"
  modele: "gemma4:e4b"     // modèle Ollama (gemma4:e4b = meilleur rapport qualité/vitesse testé)
} }];

// ===== EXTRAIRE LE TEXTE + DÉCOUPER EN MORCEAUX (~20 000 caractères) =====
const p = $('PARAMÈTRES (écris ici)').first().json;
let texte = String($json.text ?? $json.data ?? '').replace(/\r/g, '');

// Métadonnées Project Gutenberg si présentes
let titre = (texte.match(/^Title:\s*(.+)$/m) || [])[1] || '';
let auteur = (texte.match(/^Author:\s*(.+)$/m) || [])[1] || '';
// Retirer l'entête et la licence Gutenberg
const debut = texte.search(/\*\*\* ?START OF (THE|THIS) PROJECT GUTENBERG[^\n]*\n/i);
if (debut !== -1) texte = texte.substring(texte.indexOf('\n', debut) + 1);
const fin = texte.search(/\*\*\* ?END OF (THE|THIS) PROJECT GUTENBERG/i);
if (fin !== -1) texte = texte.substring(0, fin);

texte = texte.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
if (!titre) titre = p.fichier.replace(/\.[^.]+$/, '').replace(/[-_]+/g, ' ');

if (texte.length < 500) {
  throw new Error("Presque aucun texte extrait de « " + p.fichier + " » (" + texte.length +
    " caractères). Si c'est un PDF scanné (images), il faut d'abord un OCR.");
}

const TAILLE = 20000;
const paragraphes = texte.split(/\n\s*\n/);
const morceaux = [];
let courant = '';
const pousser = () => { if (courant.trim()) morceaux.push(courant.trim()); courant = ''; };
for (const para of paragraphes) {
  if (para.length > TAILLE) {                 // paragraphe géant (PDF mal structuré)
    pousser();
    const phrases = para.split(/(?<=[.!?…])\s+/);
    for (const ph of phrases) {
      if ((courant + ' ' + ph).length > TAILLE) pousser();
      courant += (courant ? ' ' : '') + ph;
    }
    pousser();
    continue;
  }
  if ((courant + '\n\n' + para).length > TAILLE) pousser();
  courant += (courant ? '\n\n' : '') + para;
}
pousser();

return morceaux.map((m, i) => ({ json: {
  numero: i + 1, total: morceaux.length, texte: m,
  titre: titre.trim(), auteur: auteur.trim(), nb_caracteres: texte.length
} }));

// ===== BODY POUR LE LECTEUR (une fiche par morceau, JSON forcé) =====
const p = $('PARAMÈTRES (écris ici)').first().json;

const system = `Tu es un lecteur analyste. Tu lis UN extrait d'un livre et tu en fais une fiche de lecture fidèle, en français (même si l'extrait est dans une autre langue).

RÈGLES ABSOLUES :
1. Tu réponds UNIQUEMENT avec un objet JSON valide conforme au schéma. Aucun texte hors JSON.
2. Tu n'utilises QUE ce qui est écrit dans l'extrait. Aucune connaissance extérieure, aucune supposition sur la suite du livre.
3. Le résumé raconte ce qui SE PASSE ou ce qui est ARGUMENTÉ dans l'extrait, dans l'ordre, avec les noms propres exacts.
4. Les citations sont COPIÉES MOT POUR MOT depuis l'extrait (même ponctuation). Elles seront vérifiées automatiquement : une citation reformulée sera rejetée.
5. Si l'extrait n'est qu'une table des matières, une préface technique ou une page de garde, dis-le simplement dans le résumé.

SCHÉMA :
{
  "resume": "150 à 250 mots",
  "idees_cles": ["2 à 5 idées ou événements majeurs"],
  "personnages_ou_acteurs": ["noms propres importants dans l'extrait"],
  "citations": ["1 à 3 phrases marquantes, copiées à l'identique"]
}`;

const prompt = `LIVRE : ${$json.titre}${$json.auteur ? ' — ' + $json.auteur : ''}
EXTRAIT ${$json.numero} sur ${$json.total}${p.consigne ? '\nANGLE DEMANDÉ : ' + p.consigne : ''}

----- DÉBUT DE L'EXTRAIT -----
${$json.texte}
----- FIN DE L'EXTRAIT -----`;

return { json: {
  model: p.modele, system, prompt, stream: false, format: 'json',
  options: { num_ctx: 16384, temperature: 0.2 }
} };

// ===== COLLECTER LES FICHES + VÉRIFIER LES CITATIONS MOT POUR MOT =====
const morceaux = $('Découper en morceaux').all().map(i => i.json);
const reponses = $input.all().map(i => i.json);

const norm = s => String(s || '')
  .replace(/[’‘`]/g, "'").replace(/[«»“”]/g, '"')
  .replace(/\s+/g, ' ').trim().toLowerCase();

const fiches = [];
const alertes = [];
let citRejetees = 0;

reponses.forEach((r, i) => {
  const m = morceaux[i];
  let brut = String(r.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  let f = null;
  const d = brut.indexOf('{'), fin = brut.lastIndexOf('}');
  if (d !== -1 && fin > d) { try { f = JSON.parse(brut.substring(d, fin + 1)); } catch (e) {} }
  if (!f || !f.resume) {
    alertes.push(`Partie ${m.numero} : fiche illisible (JSON invalide), partie ignorée.`);
    return;
  }
  const source = norm(m.texte);
  const citations = (f.citations || []).filter(c => {
    const ok = norm(c).length > 15 && source.includes(norm(c));
    if (!ok) citRejetees++;
    return ok;
  });
  fiches.push({
    numero: m.numero,
    resume: String(f.resume).trim(),
    idees_cles: f.idees_cles || [],
    personnages: f.personnages_ou_acteurs || [],
    citations
  });
});

if (!fiches.length) throw new Error("Aucune fiche exploitable : vérifier qu'Ollama répond et que le modèle existe.");

const total = morceaux[0].total;
const bloc = f => `### Partie ${f.numero}/${total}\n${f.resume}\nIdées : ${f.idees_cles.join(' ; ')}`;

// Livre court : synthèse directe. Livre long : on regroupe par 8 parties d'abord.
const TAILLE_GROUPE = 8;
const groupes = [];
for (let i = 0; i < fiches.length; i += TAILLE_GROUPE) groupes.push(fiches.slice(i, i + TAILLE_GROUPE));
const matiere = fiches.map(bloc).join('\n\n');

return [{ json: {
  titre: morceaux[0].titre, auteur: morceaux[0].auteur, nb_caracteres: morceaux[0].nb_caracteres,
  total, fiches, alertes, citations_rejetees: citRejetees,
  livre_long: matiere.length > 60000,
  groupes: groupes.map((g, k) => ({
    numero: k + 1,
    de: g[0].numero, a: g[g.length - 1].numero,
    matiere: g.map(bloc).join('\n\n')
  })),
  matiere
} }];

// ===== LIVRE LONG : un item par groupe de 8 parties =====
const p = $('PARAMÈTRES (écris ici)').first().json;
const c = $json;
return c.groupes.map(g => ({ json: {
  model: p.modele,
  system: `Tu condenses des fiches de lecture successives d'un même livre en UN résumé de section de 300 à 450 mots, en français. Tu gardes l'ordre, les noms propres exacts et les idées majeures. Tu n'ajoutes RIEN qui ne soit pas dans les fiches. Réponds directement par le texte, sans titre ni commentaire.`,
  prompt: `LIVRE : ${c.titre}\nSECTION : parties ${g.de} à ${g.a} sur ${c.total}\n\n${g.matiere}`,
  stream: false,
  options: { num_ctx: 16384, temperature: 0.2 },
  _de: g.de, _a: g.a
} }));

// ===== LIVRE LONG : assembler les résumés de sections =====
const c = $('Collecter les fiches').first().json;
const sections = $input.all().map((it, k) => {
  const g = c.groupes[k];
  const txt = String(it.json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  return `### Section ${g.numero} (parties ${g.de} à ${g.a} sur ${c.total})\n${txt}`;
});
return [{ json: { ...c, matiere: sections.join('\n\n') } }];

// ===== BODY POUR LA SYNTHÈSE FINALE (markdown) =====
const p = $('PARAMÈTRES (écris ici)').first().json;
const c = $json;
const court = p.niveau === 'court';

const plan = court
  ? `## En une phrase
(une seule phrase)

## Résumé
(300 à 400 mots, en prose)

## Idées clés
(5 puces maximum)`
  : `## En une phrase
(une seule phrase)

## Résumé
(700 à 1000 mots, en prose, qui suit l'ordre du livre)

## Structure du livre
(une puce par grand mouvement ou grande partie, avec ce qui s'y passe)

## Idées clés
(5 à 10 puces : thèses, leçons, arguments majeurs)

## Personnages / acteurs principaux
(une puce par nom : son rôle en une ligne ; omets la section si c'est un essai sans acteurs)

## Ce qu'il faut retenir
(3 à 5 puces actionnables ou mémorables)`;

const system = `Tu es un analyste littéraire. À partir de fiches de lecture successives couvrant TOUT un livre, tu rédiges sa synthèse finale en français, en markdown.

RÈGLES ABSOLUES :
1. Tu n'utilises QUE le contenu des fiches. Aucune connaissance extérieure sur le livre ou l'auteur, aucune invention.
2. Tu respectes EXACTEMENT ce plan, titres compris, et rien d'autre :

${plan}

3. Tu commences directement par « ## En une phrase ». Aucune introduction, aucun commentaire final.
4. Pas de citations entre guillemets : elles sont ajoutées séparément après vérification.
5. Si des fiches se contredisent, tu suis l'ordre du livre et tu restes prudent.`;

const prompt = `LIVRE : ${c.titre}${c.auteur ? ' — ' + c.auteur : ''}${p.consigne ? '\nANGLE DEMANDÉ : ' + p.consigne : ''}

FICHES DE LECTURE (dans l'ordre du livre) :

${c.matiere}`;

return [{ json: {
  model: p.modele, system, prompt, stream: false,
  options: { num_ctx: 32768, temperature: 0.3 }
} }];

// ===== RÉSULTAT FINAL — le résumé est ici, et dans le fichier =====
const p = $('PARAMÈTRES (écris ici)').first().json;
const c = $('Collecter les fiches').first().json;
const synthese = String($json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();

const citations = c.fiches.flatMap(f => f.citations.map(q => `> « ${q.replace(/^["«\s]+|["»\s]+$/g, '')} »\n> — partie ${f.numero}/${c.total}`));
const selection = citations.filter((_, i) => i % Math.max(1, Math.ceil(citations.length / 8)) === 0).slice(0, 8);

const lignes = [
  `# Résumé — ${c.titre}${c.auteur ? ' (' + c.auteur + ')' : ''}`,
  '',
  `> Atelier Lecture — ${new Date().toLocaleDateString('fr-FR')} · fichier : ${p.fichier} · modèle : ${p.modele} · ${c.total} parties lues (${Math.round(c.nb_caracteres / 1000)} k caractères)`,
  '> Résumé généré 100 % en local. Relire avant tout usage public : un modèle 4B peut simplifier ou confondre.',
  '',
  synthese,
  ''
];
if (selection.length) {
  lignes.push('## Citations (vérifiées mot pour mot dans le texte)', '', selection.join('\n\n'), '');
}
if (p.niveau !== 'court') {
  lignes.push('---', '', '## Annexe — fiches par partie', '');
  for (const f of c.fiches) lignes.push(`### Partie ${f.numero}/${c.total}`, f.resume, '');
}
lignes.push('---', '## Rapport de production',
  `- Parties lues : ${c.fiches.length}/${c.total}`,
  `- Mode : ${c.livre_long ? 'livre long (synthèse en 2 étages)' : 'synthèse directe'}`,
  `- Citations rejetées (non retrouvées mot pour mot) : ${c.citations_rejetees}`,
  ...c.alertes.map(a => `- ⚠️ ${a}`));

const texte = lignes.join('\n');
const slug = (c.titre || 'livre').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').substring(0, 40);
const horodatage = new Date().toISOString().substring(0, 16).replace(/[:T]/g, '-');

return [{ json: {
  RESUME: synthese,
  qualite: { parties_lues: c.fiches.length, total: c.total, citations_rejetees: c.citations_rejetees, alertes: c.alertes },
  texte,
  fileName: `/home/node/sorties/resume-${slug}-${horodatage}.md`
} }];
